[data-funnel-design="default-funnel"]{background-color:#F5F7FA;color:#1A1F36;font-family:'Sora',system-ui,Arial,sans-serif;min-height:100vh;--lg-primary:#1B3A5C;--lg-primary-dark:#0F2440;--lg-accent:#E85D26;--lg-card:#FFFFFF;--lg-border:#D2D9E5;--lg-success:#0E7C3A;--lg-error:#D32F2F;--lg-primary-wash:#E8EEF4;--lg-space-xs:0.25rem;--lg-space-sm:0.5rem;--lg-space-md:1rem;--lg-space-lg:1.5rem;--lg-space-xl:2rem;--lg-space-xxl:3rem;--lg-radius-sm:6px;--lg-radius-md:10px;--lg-radius-lg:14px;--lg-radius-xl:20px;--lg-radius-full:9999px;--lg-shadow-sm:0 1px 3px rgba(27,58,92,.06);--lg-shadow-md:0 4px 8px rgba(27,58,92,.06);--lg-shadow-lg:0 8px 24px rgba(27,58,92,.08);--lg-shadow-xl:0 16px 48px rgba(27,58,92,.10);--lg-shadow-glow:0 8px 32px rgba(232,93,38,.12);--lg-transition-step:300ms;--lg-transition-card:150ms;--lg-transition-btn:200ms;--lg-transition-progress:400ms;--lg-btn-easing:cubic-bezier(.34,1.56,.64,1);--lg-bp-mobile-max:480px;--lg-bp-small-max:400px;--lg-bp-tiny-max:375px;--lg-bp-desktop-min:640px;--lg-bp-wide-min:1024px}
[data-funnel-design="default-funnel"] .lg-content{max-width:600px;margin-left:auto;margin-right:auto;padding:1.5rem;box-sizing:border-box}
[data-funnel-design="default-funnel"] .lg-question-card{background:#FFFFFF;border:1px solid #E9EDF3;border-radius:16px;box-shadow:0 8px 28px rgba(20,32,54,.10);padding:44px 46px 40px;box-sizing:border-box;margin-left:calc(-1 * 1.5rem);margin-right:calc(-1 * 1.5rem)}
[data-funnel-design="default-funnel"] .lg-header{background-color:#FFFFFF;padding:1rem 1.5rem;box-shadow:0 1px 3px rgba(27,58,92,.06);position:sticky;top:0;z-index:20;display:flex;align-items:center;justify-content:center;text-align:center}
[data-funnel-design="default-funnel"] .lg-header-inner{width:100%;max-width:600px;display:flex;align-items:center;justify-content:space-between;gap:1rem}
[data-funnel-design="default-funnel"] .lg-logo{font-family:'Literata',serif;font-size:1.1rem;font-weight:700;color:#1B3A5C;text-decoration:none}
[data-funnel-design="default-funnel"] .lg-logo-accent{color:#E85D26}
[data-funnel-design="default-funnel"] .lg-back{background:none;border:0;cursor:pointer;color:#718096;font-size:0.875rem;font-family:inherit;padding:0;display:inline-flex;align-items:center;gap:0.25rem;min-height:44px}
[data-funnel-design="default-funnel"] .lg-back:hover{color:#1B3A5C}
[data-funnel-design="default-funnel"] .lg-disclosure{background:none;border:0;cursor:pointer;color:#718096;font-size:0.8rem;font-family:inherit;text-decoration:underline}
[data-funnel-design="default-funnel"] .lg-disclosure:hover{color:#1B3A5C}
[data-funnel-design="default-funnel"] .lg-progress{margin-bottom:2rem}
[data-funnel-design="default-funnel"] .lg-progress-track{height:8px;background-color:#E8EEF4;border-radius:9999px;overflow:hidden}
[data-funnel-design="default-funnel"] .lg-progress-fill{height:100%;background:linear-gradient(90deg,#1B3A5C,#2A5080);border-radius:9999px;transition:width var(--lg-transition-progress) ease}
[data-funnel-design="default-funnel"] .lg-progress-text{color:#1B3A5C;font-size:0.7rem;font-weight:600;margin-top:0.25rem}
[data-funnel-design="default-funnel"] .lg-category{font-size:0.8125rem;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:#E85D26;margin-bottom:12px}
[data-funnel-design="default-funnel"] .lg-headline{font-family:'Literata',serif;font-size:1.75rem;font-weight:700;line-height:1.25;color:#1A1F36;text-align:center;text-wrap:balance;margin:0 0 9px 0}
[data-funnel-design="default-funnel"] .lg-subheadline{font-size:0.825rem;color:#4A5568;text-align:center;margin:0 0 30px 0}
[data-funnel-design="default-funnel"] .lg-range-value{font-family:'Literata',serif;font-size:2.25rem;font-weight:700;color:#1A1F36;text-align:center;margin:1rem 0}
[data-funnel-design="default-funnel"] .lg-range-track{position:relative;height:8px;background-color:#E8EEF4;border-radius:9999px}
[data-funnel-design="default-funnel"] .lg-range-fill{position:absolute;left:0;top:0;height:100%;background-color:#1B3A5C;border-radius:9999px}
[data-funnel-design="default-funnel"] .lg-range-input{-webkit-appearance:none;appearance:none;width:100%;background:transparent;margin:0;min-height:44px}
[data-funnel-design="default-funnel"] .lg-range-input::-webkit-slider-thumb{-webkit-appearance:none;appearance:none;width:28px;height:28px;border-radius:9999px;background:#1B3A5C;border:3px solid #FFFFFF;box-shadow:0 2px 8px rgba(27,58,92,.25);cursor:pointer}
[data-funnel-design="default-funnel"] .lg-range-input::-moz-range-thumb{width:28px;height:28px;border-radius:9999px;background:#1B3A5C;border:3px solid #FFFFFF;box-shadow:0 2px 8px rgba(27,58,92,.25);cursor:pointer}
[data-funnel-design="default-funnel"] .lg-range-minmax{display:flex;justify-content:space-between;color:#718096;font-size:0.8125rem;margin-top:0.5rem}
[data-funnel-design="default-funnel"] .lg-btn{display:inline-flex;align-items:center;justify-content:center;gap:0.5rem;background:#1B3A5C;color:#FFFFFF;padding:14px 16px;min-height:52px;border-radius:10px;border:0;font-family:'Sora',sans-serif;font-size:0.9375rem;font-weight:600;cursor:pointer;box-sizing:border-box;transition:background var(--lg-transition-btn) var(--lg-btn-easing)}
[data-funnel-design="default-funnel"] .lg-btn:hover{background:#0F2440}
[data-funnel-design="default-funnel"] .lg-btn:active{transform:scale(0.98)}
[data-funnel-design="default-funnel"] .lg-btn:disabled, [data-funnel-design="default-funnel"] .lg-btn[aria-disabled="true"]{opacity:0.6;cursor:not-allowed}
[data-funnel-design="default-funnel"] .lg-continue{width:100%;max-width:320px;margin-top:26px;margin-left:auto;margin-right:auto;background:var(--lg-btn-bg, #1B3A5C)}
[data-funnel-design="default-funnel"] .lg-auto-advance{background:var(--lg-btn-bg, #1B3A5C)}
[data-funnel-design="default-funnel"] .lg-btn[data-loading="true"] .lg-btn-label{visibility:hidden}
[data-funnel-design="default-funnel"] .lg-btn-spinner{display:none}
[data-funnel-design="default-funnel"] .lg-btn[data-loading="true"] .lg-btn-spinner{display:inline-block;width:1em;height:1em;border:2px solid #FFFFFF;border-top-color:transparent;border-radius:9999px;animation:lg-spin 0.6s linear infinite}
@keyframes lg-spin{to{transform:rotate(360deg)}}
[data-funnel-design="default-funnel"] .lg-btn.lg-btn-answer{background:#FFFFFF;color:#1A1F36;border:2px solid #D2D9E5;transition:border-color var(--lg-transition-card), background var(--lg-transition-card)}
[data-funnel-design="default-funnel"] .lg-btn.lg-btn-answer:hover{border-color:#1B3A5C;background:#F2F6FA}
[data-funnel-design="default-funnel"] .lg-btn.lg-btn-answer[aria-checked="true"], [data-funnel-design="default-funnel"] .lg-btn.lg-btn-answer[data-selected="true"]{border-color:#1B3A5C;background:#E8EEF4;font-weight:700}
[data-funnel-design="default-funnel"] .lg-btn.lg-btn-answer:focus-visible{outline:2px solid #1B3A5C;outline-offset:2px}
[data-funnel-design="default-funnel"] .lg-badge{display:inline-flex;align-items:center;gap:8px;border:1px solid #0E7C3A;background:#F2F6FA;border-radius:10px;padding:10px 16px;color:#0E7C3A;font-size:0.875rem}
[data-funnel-design="default-funnel"] .lg-badge-icon{color:#0E7C3A;line-height:1}
[data-funnel-design="default-funnel"] .lg-secure-badge{display:inline-flex;align-items:center;gap:8px;border:1px solid #D2D9E5;background:#F2F6FA;border-radius:10px;padding:8px 12px;color:#4A5568;font-size:0.8125rem}
[data-funnel-design="default-funnel"] .lg-secure-badge-icon{color:#1B3A5C;line-height:1}
[data-funnel-design="default-funnel"] .lg-success{display:flex;flex-direction:column;align-items:center;gap:0.5rem;border:1px solid #0E7C3A;background:#F2F6FA;border-radius:14px;padding:24px 20px;text-align:center}
[data-funnel-design="default-funnel"] .lg-success-icon{color:#0E7C3A;font-size:32px;line-height:1}
[data-funnel-design="default-funnel"] .lg-success-heading{font-family:'Literata',serif;font-size:1.375rem;font-weight:700;color:#1A1F36}
[data-funnel-design="default-funnel"] .lg-success-message{color:#4A5568;font-size:0.875rem;margin:0}
[data-funnel-design="default-funnel"] .lg-trustbar{display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:1rem;margin:1rem 0}
[data-funnel-design="default-funnel"] .lg-trustbar-stacked{flex-direction:column;align-items:flex-start}
[data-funnel-design="default-funnel"] .lg-trustbar-item{display:inline-flex;align-items:center;gap:8px;color:#4A5568;font-size:0.8125rem}
[data-funnel-design="default-funnel"] .lg-trustbar-icon{color:#0E7C3A;line-height:1}
[data-funnel-design="default-funnel"] .lg-logo-strip{display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:1.5rem;margin:1rem 0}
[data-funnel-design="default-funnel"] .lg-logo-strip-img{max-height:32px;width:auto;object-fit:contain;opacity:0.85}
[data-funnel-design="default-funnel"] .lg-steps{display:flex;align-items:center;justify-content:center;gap:8px;margin-bottom:1.5rem}
[data-funnel-design="default-funnel"] .lg-step{width:10px;height:10px;border-radius:9999px;background:#E8EEF4}
[data-funnel-design="default-funnel"] .lg-step[data-active="true"]{background:#1B3A5C}
[data-funnel-design="default-funnel"] .lg-card-grid{display:grid;grid-template-columns:repeat(var(--lg-cols, 3), minmax(0, 1fr));gap:0.5rem;margin-bottom:1.5rem}
[data-funnel-design="default-funnel"] .lg-card{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:0.25rem;border:2px solid #D2D9E5;border-radius:10px;background:#FFFFFF;min-height:96px;padding:1rem;cursor:pointer;text-align:center;transition:border-color var(--lg-transition-card), background var(--lg-transition-card)}
[data-funnel-design="default-funnel"] .lg-card:hover{border-color:#1B3A5C;background:#F2F6FA}
[data-funnel-design="default-funnel"] .lg-card[aria-checked="true"], [data-funnel-design="default-funnel"] .lg-card[data-selected="true"]{border-color:#1B3A5C;background:#E8EEF4;font-weight:700}
[data-funnel-design="default-funnel"] .lg-card:focus-visible{outline:2px solid #1B3A5C;outline-offset:2px}
[data-funnel-design="default-funnel"] .lg-card[aria-disabled="true"], [data-funnel-design="default-funnel"] .lg-card:disabled{opacity:0.5;cursor:not-allowed}
[data-funnel-design="default-funnel"] .lg-card[data-error="true"]{border-color:#D32F2F}
[data-funnel-design="default-funnel"] .lg-card-icon{color:#1B3A5C;font-size:32px;line-height:1}
[data-funnel-design="default-funnel"] .lg-card-title{font-size:1rem;font-weight:700;color:#1A1F36}
[data-funnel-design="default-funnel"] .lg-card-desc{font-size:0.825rem;color:#4A5568}
[data-funnel-design="default-funnel"] .lg-card-img{max-height:32px;width:auto;object-fit:contain}
[data-funnel-design="default-funnel"] .lg-field{display:block;margin-bottom:1rem}
[data-funnel-design="default-funnel"] .lg-label{display:block;font-size:0.825rem;color:#4A5568;margin-bottom:0.25rem}
[data-funnel-design="default-funnel"] .lg-input{width:100%;box-sizing:border-box;padding:16px 18px;border:2px solid #D2D9E5;border-color:var(--lg-field-border, #D2D9E5);border-radius:12px;font-size:1rem;font-family:inherit;color:#1A1F36;min-height:44px;background:#FFFFFF}
[data-funnel-design="default-funnel"] .lg-input:focus{outline:none;border-color:#1B3A5C}
[data-funnel-design="default-funnel"] .lg-input[aria-invalid="true"]{border-color:#D32F2F}
[data-funnel-design="default-funnel"] .lg-input::placeholder{color:#718096}
[data-funnel-design="default-funnel"] .lg-dropdown{-webkit-appearance:none;-moz-appearance:none;appearance:none;background-image:url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='16' height='16' viewBox='0 0 16 16'><path fill='%235A6178' d='M4 6l4 4 4-4z'/></svg>");background-repeat:no-repeat;background-position:right 16px center;padding-right:40px}
[data-funnel-design="default-funnel"] .lg-dropdown-search{margin-bottom:0.5rem}
[data-funnel-design="default-funnel"] .lg-currency{position:relative}
[data-funnel-design="default-funnel"] .lg-currency-prefix{position:absolute;left:18px;top:50%;transform:translateY(-50%);color:#4A5568;font-size:1rem;pointer-events:none}
[data-funnel-design="default-funnel"] .lg-currency-input{padding-left:2rem}
[data-funnel-design="default-funnel"] .lg-error{color:#D32F2F;font-size:0.875rem;margin-top:0.25rem}
[data-funnel-design="default-funnel"] .lg-helper{color:#718096;font-size:0.875rem;margin-top:0.25rem}
[data-funnel-design="default-funnel"] .lg-legal{color:#718096;font-size:0.75rem;line-height:1.4}
[data-funnel-design="default-funnel"] .lg-valid{color:#0E7C3A}
[data-funnel-design="default-funnel"] .lg-banner{border:2px solid #D2D9E5;border-radius:20px;padding:1.5rem;background:#FFFFFF}
[data-funnel-design="default-funnel"] .lg-banner[data-recommended="true"]{border:2px solid #E85D26;background:#FFFAF7;box-shadow:0 4px 20px rgba(232,93,38,.12)}
[data-funnel-design="default-funnel"] .lg-banner-name{font-size:1.125rem;font-weight:700;color:#1A1F36}
[data-funnel-design="default-funnel"] .lg-banner-cta{background:#1B3A5C;color:#FFFFFF;border-radius:10px;text-transform:uppercase;padding:14px 16px;text-decoration:none;display:inline-block}
[data-funnel-design="default-funnel"] .lg-stack{display:flex;flex-direction:column}
[data-funnel-design="default-funnel"] .lg-stack[data-direction="horizontal"]{flex-direction:row;flex-wrap:wrap}
[data-funnel-design="default-funnel"] .lg-stack[data-align="start"]{align-items:flex-start}
[data-funnel-design="default-funnel"] .lg-stack[data-align="center"]{align-items:center}
[data-funnel-design="default-funnel"] .lg-stack[data-align="end"]{align-items:flex-end}
[data-funnel-design="default-funnel"] .lg-stack[data-align="stretch"]{align-items:stretch}
[data-funnel-design="default-funnel"] .lg-grid-container{display:grid;grid-template-columns:repeat(var(--lg-gc-cols-d, 3), minmax(0, 1fr));margin-bottom:1.5rem}
[data-funnel-design="default-funnel"] .lg-grid-container[data-sizing="auto"]{grid-template-columns:repeat(var(--lg-gc-cols-d, 3), auto);justify-content:center}
[data-funnel-design="default-funnel"] .lg-columns{display:grid;gap:1rem;margin-bottom:1rem}
[data-funnel-design="default-funnel"] .lg-columns[data-ratio="50/50"]{grid-template-columns:1fr 1fr}
[data-funnel-design="default-funnel"] .lg-columns[data-ratio="60/40"]{grid-template-columns:3fr 2fr}
[data-funnel-design="default-funnel"] .lg-columns[data-ratio="40/60"]{grid-template-columns:2fr 3fr}
[data-funnel-design="default-funnel"] .lg-columns[data-ratio="70/30"]{grid-template-columns:7fr 3fr}
[data-funnel-design="default-funnel"] .lg-card-panel{width:100%;margin-left:auto;margin-right:auto;box-sizing:border-box;border:1px solid #E8ECF2}
[data-funnel-design="default-funnel"] .lg-bg-panel{position:relative;overflow:hidden;padding:2rem 1.5rem;border-radius:14px}
[data-funnel-design="default-funnel"] .lg-bg-panel-img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
[data-funnel-design="default-funnel"] .lg-bg-panel-inner{position:relative}
[data-funnel-design="default-funnel"] .lg-spacer{display:block}
[data-funnel-design="default-funnel"] .lg-headerbar{display:flex;align-items:center;justify-content:space-between;gap:1rem;max-width:600px;margin-left:auto;margin-right:auto;background:#FFFFFF;padding:1rem 1.5rem;box-shadow:0 1px 3px rgba(27,58,92,.06);box-sizing:border-box}
[data-funnel-design="default-funnel"] .lg-headerbar-left, [data-funnel-design="default-funnel"] .lg-headerbar-right{display:inline-flex;align-items:center;gap:1rem}
[data-funnel-design="default-funnel"] .lg-headerbar-logo{max-height:32px;width:auto}
[data-funnel-design="default-funnel"] .lg-headerbar-secure{display:inline-flex;align-items:center;gap:0.25rem;color:#4A5568;font-size:0.8125rem}
[data-funnel-design="default-funnel"] .lg-headerbar-secure-icon{color:#1B3A5C;line-height:1}
[data-funnel-design="default-funnel"] .lg-headerbar-cta{display:inline-block;background:#1B3A5C;color:#FFFFFF;border-radius:10px;font-size:0.875rem;padding:10px 16px;text-decoration:none;font-weight:600}
[data-funnel-design="default-funnel"] .lg-footerbar{display:flex;flex-direction:column;align-items:center;gap:0.5rem;background:#F2F6FA;border-top:1px solid #E8ECF2;padding:1.5rem;margin-top:2rem;text-align:center}
[data-funnel-design="default-funnel"] .lg-footerbar-trust{display:flex;flex-wrap:wrap;justify-content:center;gap:1rem;color:#4A5568;font-size:0.8125rem}
[data-funnel-design="default-funnel"] .lg-footerbar-links{display:flex;flex-wrap:wrap;justify-content:center;gap:1rem}
[data-funnel-design="default-funnel"] .lg-footerbar-link{color:#1B3A5C;font-size:0.75rem;text-decoration:underline}
[data-funnel-design="default-funnel"] .lg-footerbar-legal{color:#718096;font-size:0.75rem;line-height:1.4}
@media (max-width: 480px){
[data-funnel-design="default-funnel"] .lg-content{padding:1rem}
[data-funnel-design="default-funnel"] .lg-question-card{padding:28px 20px 24px;margin-left:calc(-1 * 1rem);margin-right:calc(-1 * 1rem)}
[data-funnel-design="default-funnel"] .lg-headline{font-size:1.375rem}
[data-funnel-design="default-funnel"] .lg-continue{width:100%}
[data-funnel-design="default-funnel"] .lg-card-grid{grid-template-columns:1fr}
[data-funnel-design="default-funnel"] .lg-stack[data-direction="horizontal"]{flex-direction:column}
[data-funnel-design="default-funnel"] .lg-grid-container{grid-template-columns:repeat(var(--lg-gc-cols-m, 1), minmax(0, 1fr))}
[data-funnel-design="default-funnel"] .lg-grid-container[data-sizing="auto"]{grid-template-columns:repeat(var(--lg-gc-cols-m, 1), auto)}
[data-funnel-design="default-funnel"] .lg-columns[data-mobile="stack"]{grid-template-columns:1fr}
}
